INSERT INTO `flight_routes` VALUES (1,'LHR','LOS','london-lhr-to-lagos-los',3124,410,1,618.53,'Royal Air Maroc',1,'{\"origin\":\"LHR\",\"destination\":\"LOS\",\"destination_city\":\"Lagos\",\"airlines_operating\":[{\"name\":\"Royal Air Maroc\",\"flight_type\":\"Connecting\",\"min_price\":618.53},{\"name\":\"Rwandair Express\",\"flight_type\":\"Connecting\",\"min_price\":725.58},{\"name\":\"Egyptair\",\"flight_type\":\"Connecting\",\"min_price\":740.78},{\"name\":\"Ethiopian Airlines\",\"flight_type\":\"Connecting\",\"min_price\":788.98},{\"name\":\"KLM Royal Dutch Airlines\",\"flight_type\":\"Connecting\",\"min_price\":800.04},{\"name\":\"Air France\",\"flight_type\":\"Connecting\",\"min_price\":800.13},{\"name\":\"Lufthansa\",\"flight_type\":\"Connecting\",\"min_price\":851.18},{\"name\":\"Turkish Airlines\",\"flight_type\":\"Connecting\",\"min_price\":862.35},{\"name\":\"Emirates\",\"flight_type\":\"Connecting\",\"min_price\":1089.98},{\"name\":\"British Airways\",\"flight_type\":\"Direct\",\"min_price\":1166.04},{\"name\":\"Virgin Atlantic Airways\",\"flight_type\":\"Direct\",\"min_price\":1245.46},{\"name\":\"Qatar Airways\",\"flight_type\":\"Connecting\",\"min_price\":1287.16}],\"faqs\":[{\"question\":\"How long is the flight from London Heathrow to Lagos?\",\"answer\":\"A direct flight from London Heathrow (LHR) to Murtala Muhammed International Airport (LOS) takes roughly 6 hours 50 minutes eastbound. Connecting itineraries via Kigali, Addis Ababa or Casablanca typically take 11 to 16 hours depending on the layover.\"},{\"question\":\"Which airlines fly direct from London to Lagos?\",\"answer\":\"Air Peace, British Airways and Virgin Atlantic all operate direct flights between London Heathrow and Lagos. Air Peace is often the most affordable direct option, while British Airways offers multiple weekly frequencies.\"},{\"question\":\"What is the cheapest time of year to fly to Lagos?\",\"answer\":\"Fares tend to drop outside the peak Christmas, Easter and summer school-holiday windows. Early November and late January are regularly the cheapest periods, with savings compared to December peaks.\"},{\"question\":\"How much luggage is included on London to Lagos flights?\",\"answer\":\"Most direct carriers on this route include at least one checked bag of 23kg in the fare. Low-cost and connecting options may charge extra \\u2014 always verify baggage allowances before confirming your booking.\"},{\"question\":\"Do I need a visa to visit Nigeria from the UK?\",\"answer\":\"Yes. British citizens need a Nigerian visa before travel. Nurud Travels can help you plan the visa and travel requirements around your flight booking.\"}],\"seasonal_tips\":[\"Book at least 8-10 weeks ahead for the lowest fares on the LHR-LOS route.\",\"Avoid travelling in the final three weeks of December if you want to control your budget.\"],\"last_live_update\":\"2026-09-11 22:12:06\"}','2026-09-11 15:28:17','2026-09-11 21:12:06');
INSERT INTO `flight_routes` VALUES (2,'LHR','ABV','london-lhr-to-abuja-abv',2795,375,1,685.03,'Ethiopian Airlines',1,'{\"origin\":\"LHR\",\"destination\":\"ABV\",\"destination_city\":\"Abuja\",\"airlines_operating\":[{\"name\":\"Ethiopian Airlines\",\"flight_type\":\"Connecting\",\"min_price\":685.03},{\"name\":\"Air France\",\"flight_type\":\"Connecting\",\"min_price\":685.14},{\"name\":\"KLM Royal Dutch Airlines\",\"flight_type\":\"Connecting\",\"min_price\":731.81},{\"name\":\"Egyptair\",\"flight_type\":\"Connecting\",\"min_price\":743.15},{\"name\":\"Qatar Airways\",\"flight_type\":\"Connecting\",\"min_price\":747.62},{\"name\":\"British Airways\",\"flight_type\":\"Direct\",\"min_price\":837.44},{\"name\":\"Lufthansa\",\"flight_type\":\"Connecting\",\"min_price\":1151.53},{\"name\":\"Turkish Airlines\",\"flight_type\":\"Connecting\",\"min_price\":1187.1}],\"faqs\":[{\"question\":\"How long does it take to fly from London to Abuja?\",\"answer\":\"Direct flights from London Heathrow to Nnamdi Azikiwe International Airport (ABV) take around 6 hours 15 minutes. One-stop itineraries through Addis Ababa or Frankfurt usually take 10 to 14 hours.\"},{\"question\":\"Which airlines operate direct flights from London to Abuja?\",\"answer\":\"British Airways and Air Peace operate direct services between London Heathrow and Abuja. British Airways tends to offer the most consistent schedule on this route.\"},{\"question\":\"Is Abuja more expensive to fly to than Lagos?\",\"answer\":\"Abuja fares are usually slightly higher than Lagos because there are fewer direct frequencies. Connecting options via Ethiopian Airlines or Lufthansa are typically the cheapest way to reach Abuja.\"},{\"question\":\"When is the best time to book flights to Abuja?\",\"answer\":\"Book 6-10 weeks before departure for the best value. Prices rise sharply in the two weeks before departure and across the December holiday period.\"}],\"seasonal_tips\":[\"Abuja has a dry season from November to March \\u2014 the most comfortable time to travel.\",\"Consider flying into Lagos and taking the domestic leg to Abuja if direct fares spike.\"],\"last_live_update\":\"2026-09-11 22:12:29\"}','2026-09-11 15:28:17','2026-09-11 21:12:29');
